const src = $input.item.json;
const raw = src.output || src.text || (src.content && src.content.parts && src.content.parts[0] && src.content.parts[0].text) || '';
const mail = $('Appel depuis un workflow').item.json;
let r = { statut: 'EN_ATTENTE', entreprise: null, poste: null, contact_rh: null, prochaine_etape: null, langue: 'FR', confiance: 0, priorite: 5, review_manuel: true };
try {
  const p = typeof raw === 'object' ? raw : JSON.parse(String(raw).replace(/```json|```/g, '').trim());
  if (['POSITIF', 'REFUS', 'EN_ATTENTE', 'HORS_SCOPE'].includes(p.statut)) {
    r = {
      statut: p.statut,
      entreprise: p.entreprise ?? null,
      poste: p.poste ?? null,
      contact_rh: p.contact_rh ?? null,
      prochaine_etape: p.prochaine_etape ?? null,
      langue: p.langue === 'EN' ? 'EN' : 'FR',
      confiance: Math.min(1, Math.max(0, Number(p.confiance) || 0)),
      priorite: Math.min(10, Math.max(1, Math.round(Number(p.priorite) || 5))),
      review_manuel: false
    };
  }
} catch (e) {}
return { json: { ...r, emailId: mail.emailId, from: mail.from, subject: mail.subject, date: mail.date } };

